 [T('WHERE','去哪吃'),T('Yuelu: a starting point for late-night dining','岳麓区：高评分夜宵的起点'),food.length?(food.reduce((s,p)=>s+p[5],0)/food.length).toFixed(2)+'/5':'—',T(`${food.length} rated restaurants; highest district mean in this snapshot. Compare menus, prices and review counts before choosing.`,`${food.length}家有评分餐厅，快照中区均分最高。再结合菜系、预算与点评数选店。`)],
 [T('WHEN','何时去'),T('For more dinner options, go earlier','想有更多餐厅可选，就早点出发'),T(`${time(st.h)}: ${pct(p)} still open`,`${time(st.h)}仍营业${pct(p)}`),T(`Of ${F(curves[0].base)} restaurants open on Wednesday at 21:00, ${F(curves[0].values[st.h])} remain open at ${time(st.h)}.`,`周三21:00营业的${F(curves[0].base)}家餐厅中，${time(st.h)}仍有${F(curves[0].values[st.h])}家营业。`)],
 [T('AFTER DINNER','吃完去哪'),T('After dinner: mahjong & internet cafés','吃完夜宵，还能打牌、上网'),F(mahjong+internet)+T(' listings','家'),T(`At 03:00: ${F(mahjong)} chess, cards & mahjong listings; ${F(internet)} esports & internet cafés. Subtypes identified from venue names.`,`03:00棋牌／麻将${F(mahjong)}家，电竞／网咖${F(internet)}家；细分依据店名识别。`)],
 [T('WHERE TO STAY','住宿选择'),T('Before booking, check nearby services','选住宿，先查目的地周边记录'),'500 m / 1 km',T('Select your planned stay on the map. Check listed-open dining, convenience shops and pharmacies within each straight-line radius.','在地图选择住处，查看直线500米或1公里内的夜宵、便利零售和药店营业记录。')]
